/* Geographical coordinates 

To display coordinates using the notation in the source code, write this in your User:Username/monobook.css:
   .geo-default { display: inline } .geo-nondefault { display: none } 
   .geo-dec { display: inline } .geo-dms { display: inline }

To display coordinates using decimal notation, write this in your User:Username/monobook.css:
   .geo-default { display: inline } .geo-nondefault { display: inline } 
   .geo-dec { display: inline } .geo-dms { display: none }

To display coordinates using DMS notation, write this in your User:Username/monobook.css:
   .geo-default { display: inline } .geo-nondefault { display: inline } 
   .geo-dec { display: none }   .geo-dms { display: inline }

To display coordinates in both decimal and DMS notation, write this in your User:Username/monobook.css:
   .geo-default { display: inline } .geo-nondefault { display: inline } 
   .geo-dec { display: inline }   .geo-dms { display: inline }
   .geo-multi-punct { display: inline }

See [[Template:Coor link]] for how these are used.

Note that the classes "geo", "longitude", and "latitude" are not just styles but also used by the [[Geo microformat]], so the names should not be changed.

*/

.geo-default { display: inline; }
.geo-nondefault { display: none; }
.geo-dms { display: inline; }
.geo-dec { display: inline; }
.geo-multi-punct { display: none; }

.longitude .latitude {
  white-space: nowrap;
}

/* This is used for the Geo microformat, but no style is needed for now other than .geo-dec. */
.geo { }

/***** end Geo-related */

/* When <div class="nonumtoc"> is used on the table of contents, the ToC will display without numbers */
.nonumtoc .tocnumber { display:none; }
.nonumtoc #toc ul,
.nonumtoc .toc ul {
  line-height: 1.5em;
  list-style: none;
  margin: .3em 0 0;
  padding: 0;
}
.nonumtoc #toc ul ul, 
.nonumtoc .toc ul ul { 
margin: 0 0 0 2em; 
}

/* Allow limiting of which header levels are shown in a TOC; <div class="toclimit-3">, for
   instance, will limit to showing ==headings== and ===headings=== but no further (as long as
   there are no =headings= on the page, which there shouldn't be according to the MoS). */
.toclimit-2 .toclevel-2 {display:none;}
.toclimit-3 .toclevel-3 {display:none;}
.toclimit-4 .toclevel-4 {display:none;}
.toclimit-5 .toclevel-5 {display:none;}
.toclimit-6 .toclevel-6 {display:none;}
.toclimit-7 .toclevel-7 {display:none;}

/* Allow transcluded pages to display in lists rather than a table. Compatible in Firefox; incompatible in IE6. */
.listify td {display:list-item}
.listify tr {display:block}
.listify table {display:block}

/* Styling for Template:Quote */

blockquote.templatequote { margin-top: 0; }

blockquote.templatequote div.templatequotecite { 
    line-height: 1em;
    text-align: left;
    padding-left: 2em;
    margin-top: 0;
}

blockquote.templatequote div.templatequotecite cite {
    font-size: smaller;
}

div.user-block {
    padding: 5px;
    border: 1px solid #A9A9A9;
    background-color: #FFEFD5;
}

/* Prevents line breaks in links; see docs at Template:Nowraplinks */

.nowraplinks a {
    white-space: nowrap;
}

/* Enables borders on PNG images in IE 5.5 and 6 */

.thumbborder {
border:1px solid #DDDDDD;
}

/* Support for script templates. The inherit declaration resets the font for all browsers except MSIE6.  The empty comment must remain. */
.IPA {
        font-family: DejaVu Sans, Segoe UI, Lucida Grande, Lucida Sans Unicode, Charis SIL, Doulos SIL, Code2000, Gentium, Gentium Alternative, TITUS Cyberbit Basic, Arial Unicode MS;
        font-family /**/:inherit;
}
.Unicode {
        font-family: TITUS Cyberbit Basic, Code2000, Doulos SIL, Chrysanthi Unicode, Bitstream Cyberbit, Bitstream CyberBase, Bitstream Vera, Thryomanes, Gentium, GentiumAlt, Visual Geez Unicode, Lucida Grande, Tahoma, Arial Unicode MS, Microsoft Sans Serif, Lucida Sans Unicode;
        font-family /**/:inherit;
}
/* Arabic */
.AR {
        font-family: Tahoma, Arial Unicode MS, Code2000, Traditional Arabic; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Bengali */
.BN {
        font-family: UniBangla, Arial Unicode MS, Code2000, Likhan, UT Bengali Dhaka, Vrinda; 
        font-family /**/:inherit;
        font-size: 130%;
}
/* Persian */
.FA {
        font-family: Tahoma; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Kashmiri */
.KS {
        font-family: Tahoma; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Kurdish */
.KU {
        font-family: Tahoma; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Latin Extended-B */
.latinx {
        font-family: TITUS Cyberbit Basic, Code2000, Microsoft Sans Serif;
        font-family /**/:inherit;
}
/* Polytonic Greek */
.polytonic {
        font-family: Athena, Gentium, Palatino Linotype, Arial Unicode MS, Lucida Sans Unicode, Lucida Grande, Code2000; 
        font-family /**/:inherit;
}
/* Russian and other Cyrillic */
.RU {
        font-family: Arial Unicode MS, Gentium, Code2000, Lucida Sans Unicode; 
        font-family /**/:inherit;
}
/* Sindhi */
.SD {
        font-family: MB Sindhi, MBSarang Sattar, MB Bhitai Sattar, MB Lateefi, Ayaz Gul, Tahoma; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Thai */
.TH {
        font-family: Arial Unicode MS, Code2000; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Urdu */
.UR {
        font-family: Tahoma; 
        font-family /**/:inherit;
        font-size: 125%;
}
/* Han characters - added 30/5/2008 Moilleadóir */
.Han {
        font-size: 125%;
}


