// Optionen für das Sonderzeichenmenü in [[MediaWiki:Edittools]] ([[:en:MediaWiki:Monobook.js|Quelle]]; siehe [[MediaWiki:Monobook.js]])
// Spacebirdy stuff :)

 function addCharSubsetMenu() { //must match [[MediaWiki:Edittools]]
   var specialchars = document.getElementById('specialchars');

   if (specialchars) {
     var menu = "<select id=\"charSubsetControl\" style=\"display:inline\" onChange=\"chooseCharSubset(selectedIndex)\">";
     menu += "<option>IPA</option>";
     menu += "<option>Araibís</option>";
     menu += "<option>Fraincis</option>";
     menu += "<option>Gearmáinis</option>";
     menu += "<option>Gréigis</option>";
     menu += "<option>Lochlannis</option>";
     menu += "<option>Rúisis</option>";
     menu += "<option>Spáinnis</option>";
     menu += "</select>";
     specialchars.innerHTML = menu + specialchars.innerHTML;

    /* default subset from cookie */
    var s = parseInt( $.cookie('edittoolscharsubset') );
    if ( isNaN(s) ) s = 0;

    /* update dropdown control to value of cookie */
    document.getElementById('charSubsetControl').selectedIndex = s; 

    /* display the subset indicated by the cookie */
    chooseCharSubset( s );

   }
 }

 /* select subsection of special characters */
 function chooseCharSubset(s) {
   var l = document.getElementById('specialchars').getElementsByTagName('p');
   for (var i = 0; i < l.length ; i++) {
     l[i].style.display = i == s ? 'inline' : 'none';
     l[i].style.visibility = i == s ? 'visible' : 'hidden';
   }
   $.cookie('edittoolscharsubset', s);
 }

 /* inserting the drop-down-menu */
 function customizeWiktionary() {
   addCharSubsetMenu();
 }

 $(customizeWiktionary);


/*
==Drop-down language preload menu for [[MediaWiki:Noexactmatch]]==
*/
// and [[Wiktionary:Project-Newarticletext]]==
// copied from en:wikt 2009/05/21 Moilleadóir

 function addNogoPreloadMenu() {
  var preloadGuide = document.getElementById('preloadGuide');
  if (preloadGuide) {
   preloadGuide.style.display = 'inline-block';
   var menu = "<select style=\"float: left; display: inline-block; margin: 0 0 0.4em 0.5em;\" onChange=\"showPreloads(selectedIndex)\">";
   menu += "<option>Teanga · Language</option>";
   menu += "<option>Béarla · English</option>";
   menu += "<option>Fraincis · Français</option>";
   menu += "<option>Íoslainnis · íslenska</option>";
   menu += "<option>Isiltíris · Nederlands</option>";
   menu += "<option>Ocsatáinis · Occitan</option>";
   menu += "</select>";
   var menuDiv = document.getElementById('entryTemplateMenu');
   menuDiv.innerHTML = menu;
   showPreloads(0);
  }
 }
 $(addNogoPreloadMenu);

 function showPreloads(selectedIndex) {
  var languageOptions = document.getElementById('preloadGuide').getElementsByTagName('table');
  for (var i = 0; i < languageOptions.length ; i++) {
    if (languageOptions[i].className == "PTLanguage") {
      languageOptions[i].style.display = i == selectedIndex ? 'block' : 'none';
    }
  }
 }

