// see also [[MediaWiki:Common.css]] #interwiki-completelist
 /** Main Page layout fixes *********************************************************
  *
  *  Description:        Various layout fixes for the main page, including an
  *                      additional link to the complete list of languages available
  *  Maintainers: [[User:AzaToth]], [[User:R. Koot]], [[User:Alex Smotrov]]
  */
 function mainPageAppendCompleteListLink() {
    mw.util.addPortletLink('p-lang', '//meta.wikimedia.org/wiki/List_of_Wiktionaries',
                   'Liosta iomlán', 'interwiki-completelist', 'Liosta na Vicífhoclóirí uile');
 }

 if ( mw.config.get('wgIsMainPage') ) {
        $( mainPageAppendCompleteListLink );
 }

// From [[w:en:MediaWiki:Common.js]] 20/6/2008 NB: string to translate!
/** Interwiki links to featured articles ***************************************
 *
 *  Description: Highlights interwiki links to featured articles (or
 *               equivalents) by changing the bullet before the interwiki link
 *               into a star.
 *  Maintainers: [[User:R. Koot]]
 */

function LinkFA() 
{
    if ( document.getElementById( "p-lang" ) ) {
        var InterwikiLinks = document.getElementById( "p-lang" ).getElementsByTagName( "li" );

        for ( var i = 0; i < InterwikiLinks.length; i++ ) {
            if ( document.getElementById( InterwikiLinks[i].className + "-fa" ) ) {
                InterwikiLinks[i].className += " FA";
                InterwikiLinks[i].title = "Is alt sainiúil é seo i dteanga eile.";
            }
        }
    }
}

$( LinkFA );

